  v_npts     int;
BEGIN
  INSERT INTO public.rivers (river_name, slug, state, gauge_label, usgs_site_no, is_active, latitude, longitude)
  VALUES ('Snake River (display)', 'snake-river-display', 'ID', 'Display only', '00000000', false, 43.34, -111.99)
  ON CONFLICT (slug) DO UPDATE SET river_name = EXCLUDED.river_name
  RETURNING id INTO v_river_id;

  RAISE NOTICE 'snake-river-display id: %', v_river_id;

  INSERT INTO public.river_geometries (river_id, geom, updated_at)
  VALUES (
    v_river_id,
    ST_GeomFromGeoJSON(v_geojson),
    now()
  )
  ON CONFLICT (river_id) DO UPDATE
    SET geom = EXCLUDED.geom, geom_simplified = NULL, updated_at = now();

  SELECT ST_NPoints(geom) INTO v_npts
  FROM public.river_geometries WHERE river_id = v_river_id;

  RAISE NOTICE 'snake-river-display geometry: % pts', v_npts;

  IF v_npts < 5000 THEN
    RAISE EXCEPTION 'Too few points: % — geometry may be wrong', v_npts;
  END IF;
END;
